<%- include('partials/head', { title: 'Meus pedidos' }) %>
<%- include('partials/header') %>

<section class="page-title">
  <h1>Meus pedidos</h1>
  <p>Acompanhe aqui todos os pedidos feitos pela sua conta.</p>
</section>

<% if (orders.length === 0) { %>
  <div class="card center">
    <p>Você ainda não fez nenhum pedido.</p>
    <a class="button" href="/">Ver cardápio</a>
  </div>
<% } %>

<div class="orders">
  <% orders.forEach(order => { %>
    <article class="card order">
      <div class="order-head">
        <div>
          <h2>Pedido #<%= order.id %></h2>
          <p class="muted">Criado em <%= order.created_at %></p>
        </div>
        <span class="status"><%= order.status %></span>
      </div>

      <ul class="items">
        <% itemsByOrder[order.id].forEach(item => { %>
          <li>
            <span><%= item.quantity %>x <%= item.name || 'Prato removido' %></span>
            <strong><%= formatMoney(item.quantity * item.unit_price) %></strong>
          </li>
        <% }) %>
      </ul>

      <% if (order.notes) { %>
        <p><strong>Observações:</strong> <%= order.notes %></p>
      <% } %>

      <div class="total">
        Total: <%= formatMoney(order.total) %>
      </div>
    </article>
  <% }) %>
</div>

<%- include('partials/footer') %>

=== views/manager-menu.ejs ===
<%- include('partials/head', { title: 'Gerenciar cardápio' }) %>
<%- include('partials/header') %>

<section class="page-title">
  <h1>Gerenciar cardápio</h1>
  <p>Cadastre, edite ou remova pratos do restaurante.</p>
</section>

<div class="manager-layout">
  <section class="card">
    <h2><%= editing ? 'Editar prato' : 'Cadastrar prato' %></h2>

    <form action="<%= editing ? '/gerente/cardapio/' + editing.id + '/editar' : '/gerente/cardapio' %>" method="POST">
      <label>
        Nome do prato
        <input type="text" name="name" required value="<%= editing ? editing.name : '' %>">
      </label>

      <label>
        Descrição
        <textarea name="description" rows="4"><%= editing ? editing.description : '' %></textarea>
      </label>

      <label>
        Preço
        <input type="number" name="price" required min="0.01" step="0.01" value="<%= editing ? editing.price : '' %>">
      </label>

      <label class="checkbox">
        <input type="checkbox" name="available" <%= !editing || editing.available ? 'checked' : '' %>>
        Disponível para clientes
      </label>

      <button class="button full" type="submit"><%= editing ? 'Salvar alterações' : 'Cadastrar prato' %></button>

      <% if (editing) { %>
        <a class="button secondary full" href="/gerente/cardapio">Cancelar edição</a>
      <% } %>
    </form>
  </section>

